css:
/* Relay is a developer tool for watching webhooks. Its look will live in three places: the landing hero, a dashboard
   tile people stare at all day, and the app icon next to its name. Cards set --bg --fg --ac --soft (palette),
   --display --body (type), --radius (corners) and --grid (background texture). */
.spec { background: var(--grid), var(--bg); background-color: var(--bg); color: var(--fg); font-family: var(--body), system-ui, sans-serif; }
.spec h2 { font-family: var(--display), system-ui, sans-serif; margin: 0; line-height: 1; }

/* Landing hero: nav, headline, one line, a primary and a quiet button. */
.L-hero { padding: 18px 20px 22px; display: flex; flex-direction: column; gap: 14px; }
.L-hero nav { display: flex; justify-content: space-between; font-size: 12px; opacity: .8; }
.L-hero nav b { font-family: var(--display), system-ui; font-size: 15px; opacity: 1; }
.L-hero h2 { font-size: 40px; margin-top: auto; text-wrap: balance; }
.L-hero p { margin: 0; font-size: 14px; line-height: 1.45; opacity: .8; max-width: 30ch; }
.L-hero .cta { display: flex; gap: 8px; margin-bottom: 8px; }
.L-hero .cta span { padding: 10px 14px; border-radius: var(--radius); font-size: 13px; font-weight: 600; border: 1px solid var(--fg); }
.L-hero .cta span:first-child { background: var(--ac); color: var(--bg); border-color: var(--ac); }

/* Dashboard tile: a metric, a sparkline of CSS bars, three event rows with status dots. */
.L-tile { padding: 18px; display: grid; align-content: center; }
.L-tile .panel { background: var(--soft); border-radius: var(--radius); padding: 16px; display: grid; gap: 10px; border: 1px solid color-mix(in srgb, var(--fg) 15%, transparent); }
.L-tile small { font-size: 11px; text-transform: uppercase; letter-spacing: .1em; opacity: .7; }
.L-tile h2 { font-size: 44px; }
.L-tile .spark { height: 46px; display: flex; align-items: end; gap: 3px; }
.L-tile .spark i { flex: 1; background: var(--ac); border-radius: calc(var(--radius) / 4) calc(var(--radius) / 4) 0 0; opacity: .85; }
.L-tile .spark i:nth-child(1) { height: 30% } .L-tile .spark i:nth-child(2) { height: 55% } .L-tile .spark i:nth-child(3) { height: 40% }
.L-tile .spark i:nth-child(4) { height: 80% } .L-tile .spark i:nth-child(5) { height: 60% } .L-tile .spark i:nth-child(6) { height: 95% }
.L-tile .spark i:nth-child(7) { height: 70% } .L-tile .spark i:nth-child(8) { height: 50% }
.L-tile ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; font-size: 12px; font-family: var(--mono, var(--body)), monospace; }
.L-tile li::before { content: ""; display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--ac); margin-right: 8px; }
.L-tile li:last-child::before { background: transparent; border: 2px solid var(--fg); box-sizing: border-box; }

/* App icon: the mark at icon size on its tile, with the name and a one-line pitch as on a store page. */
.L-icon { display: grid; place-items: center; align-content: center; gap: 16px; padding: 24px; text-align: center; }
.L-icon .ic { width: 112px; height: 112px; border-radius: calc(var(--radius) * 1.6); background: var(--ac); display: grid; place-items: center; box-shadow: 0 14px 28px -14px rgba(0,0,0,.5); }
.L-icon .ic svg { width: 64px; height: 64px; stroke: var(--bg); fill: none; stroke-width: 7; stroke-linecap: round; stroke-linejoin: round; }
.L-icon h2 { font-size: 34px; }
.L-icon p { margin: 0; font-size: 14px; opacity: .75; max-width: 24ch; }
